from fastapi import APIRouter, HTTPException, Request, Response, status

from ctxd.app.ingestion.loaders import DocumentLoadError
from ctxd.app.models.domain import (
    DocumentIngestRequest,
    DocumentIngestResponse,
    LexicalIndexStatistics,
    QueryRequest,
    QueryResponse,
    SemanticIndexStatistics,
)
from ctxd.app.observability.metrics import render_metrics
from ctxd.app.runtime import RuntimeServices
from ctxd.app.storage.errors import RetrievalTimeoutError, StorageError

router = APIRouter()


def _services(request: Request) -> RuntimeServices:
    services: RuntimeServices = request.app.state.services
    return services


def _require_tenant(request: Request, claimed_tenant: str) -> str:
    authenticated_tenant = str(request.state.tenant_id)
    if authenticated_tenant == "unknown":
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="x-tenant-id header is required",
        )
    if authenticated_tenant != claimed_tenant:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="tenant_id does not match the authenticated tenant",
        )
    return authenticated_tenant


@router.get("/health")
async def health() -> dict[str, str]:
    return {"status": "ok"}


@router.get("/metrics", include_in_schema=False)
async def metrics() -> Response:
    body, content_type = render_metrics()
    return Response(content=body, media_type=content_type)


@router.post("/v1/documents", status_code=status.HTTP_201_CREATED)
def ingest_document(
    request_body: DocumentIngestRequest,
    request: Request,
    response: Response,
) -> DocumentIngestResponse:
    tenant_id = _require_tenant(request, request_body.tenant_id)
    try:
        document, chunks, created = _services(request).ingestion.ingest_content(
            content=request_body.content,
            source_path=request_body.source_path,
            source_type=request_body.source_type,
            tenant_id=tenant_id,
            metadata=request_body.metadata,
        )
    except DocumentLoadError as exc:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,
            detail=str(exc),
        ) from exc
    except StorageError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="document storage is unavailable",
        ) from exc
    if not created:
        response.status_code = status.HTTP_200_OK
    return DocumentIngestResponse(document=document, chunks=chunks, created=created)


@router.post("/v1/query")
def query(request_body: QueryRequest, request: Request) -> QueryResponse:
    tenant_id = _require_tenant(request, request_body.tenant_id)
    try:
        context = _services(request).assembler.assemble(
            query=request_body.query,
            tenant_id=tenant_id,
            top_k=request_body.top_k,
            max_context_tokens=request_body.max_context_tokens,
            retrieval_mode=request_body.retrieval_mode,
        )
    except RetrievalTimeoutError as exc:
        raise HTTPException(
            status_code=status.HTTP_504_GATEWAY_TIMEOUT,
            detail="retrieval timed out",
        ) from exc
    except StorageError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="retrieval subsystem is unavailable",
        ) from exc
    return QueryResponse(
        answer="Inference is not implemented yet.",
        request_id=request.state.request_id,
        trace_id=request.state.trace_id,
        context=context,
        model_decision=None,
        metadata={"tenant_id": tenant_id, "task_type": request_body.task_type},
    )


@router.get("/v1/index/semantic-statistics")
def semantic_index_statistics(request: Request) -> SemanticIndexStatistics:
    tenant_id = str(request.state.tenant_id)
    if tenant_id == "unknown":
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST, detail="x-tenant-id header is required"
        )
    try:
        return _services(request).semantic_retriever.statistics(tenant_id)
    except StorageError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="semantic index statistics are unavailable",
        ) from exc


@router.get("/v1/index/statistics")
def index_statistics(request: Request) -> LexicalIndexStatistics:
    tenant_id = str(request.state.tenant_id)
    if tenant_id == "unknown":
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="x-tenant-id header is required",
        )
    try:
        return _services(request).retriever.statistics(tenant_id)
    except StorageError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="index statistics are unavailable",
        ) from exc

from dataclasses import dataclass
from typing import Protocol, runtime_checkable

from ctxd.app.config.settings import Settings, get_settings
from ctxd.app.context.assembler import ContextAssembler
from ctxd.app.ingestion.chunking import StructureAwareChunker
from ctxd.app.ingestion.service import IngestionService
from ctxd.app.retrieval.index import LexicalIndex, SemanticIndex
from ctxd.app.retrieval.lexical import BM25Retriever
from ctxd.app.retrieval.semantic import (
    EmbeddingModel,
    FakeHashEmbeddingProvider,
    RealEmbeddingProvider,
    SemanticRetriever,
)
from ctxd.app.storage.documents import DocumentStore, InMemoryDocumentStore
from ctxd.app.storage.postgres import PostgresDocumentStore


class CorpusBackend(DocumentStore, LexicalIndex, SemanticIndex, Protocol):
    pass


@runtime_checkable
class ManagedBackend(Protocol):
    def start(self) -> None: ...

    def close(self) -> None: ...


@dataclass(frozen=True)
class RuntimeServices:
    store: CorpusBackend
    ingestion: IngestionService
    retriever: BM25Retriever
    semantic_retriever: SemanticRetriever
    assembler: ContextAssembler

    def start(self) -> None:
        if isinstance(self.store, ManagedBackend):
            self.store.start()

    def close(self) -> None:
        if isinstance(self.store, ManagedBackend):
            self.store.close()


def create_runtime(
    store: CorpusBackend | None = None,
    settings: Settings | None = None,
) -> RuntimeServices:
    resolved_settings = settings or get_settings()
    resolved_store: CorpusBackend
    if store is not None:
        resolved_store = store
    elif resolved_settings.storage_backend == "postgres":
        resolved_store = PostgresDocumentStore(
            resolved_settings.database_url,
            pool_min_size=resolved_settings.database_pool_min_size,
            pool_max_size=resolved_settings.database_pool_max_size,
            connection_timeout_seconds=resolved_settings.database_connection_timeout_seconds,
            query_timeout_ms=resolved_settings.database_query_timeout_ms,
        )
    else:
        resolved_store = InMemoryDocumentStore()
    embedding_model: EmbeddingModel
    if resolved_settings.embedding_provider == "model2vec":
        embedding_model = RealEmbeddingProvider(
            cache_dir=resolved_settings.embedding_cache_dir,
            offline=resolved_settings.embedding_offline,
            batch_size=resolved_settings.embedding_batch_size,
        )
    else:
        embedding_model = FakeHashEmbeddingProvider(
            dimension=resolved_settings.embedding_dimension,
            version=resolved_settings.embedding_version,
        )
    ingestion = IngestionService(resolved_store, StructureAwareChunker(), embedding_model)
    retriever = BM25Retriever(resolved_store)
    semantic_retriever = SemanticRetriever(resolved_store, embedding_model)
    return RuntimeServices(
        store=resolved_store,
        ingestion=ingestion,
        retriever=retriever,
        semantic_retriever=semantic_retriever,
        assembler=ContextAssembler(retriever, semantic_retriever),
    )

import hashlib
from pathlib import Path
from typing import Protocol

from ctxd.app.models.domain import Document, DocumentSourceType

Metadata = dict[str, str | int | float | bool | None]


class DocumentLoadError(ValueError):
    """Raised when a source cannot be loaded as a supported document."""


class DocumentLoader(Protocol):
    def load(
        self,
        source_path: Path,
        tenant_id: str,
        metadata: Metadata | None = None,
    ) -> Document: ...


def normalize_content(content: str) -> str:
    return content.replace("\r\n", "\n").replace("\r", "\n")


def content_sha256(content: str) -> str:
    return hashlib.sha256(content.encode("utf-8")).hexdigest()


def deterministic_document_id(tenant_id: str, source_path: str) -> str:
    identity = f"{tenant_id}\0{source_path}"
    return f"doc_{hashlib.sha256(identity.encode()).hexdigest()[:24]}"


def document_from_content(
    *,
    content: str,
    source_path: str,
    source_type: DocumentSourceType,
    tenant_id: str,
    metadata: Metadata | None = None,
) -> Document:
    normalized = normalize_content(content)
    if not normalized.strip():
        raise DocumentLoadError("document content is empty")
    normalized_path = Path(source_path).as_posix()
    combined_metadata: Metadata = {
        "extension": Path(normalized_path).suffix.lower(),
        "encoding": "utf-8",
    }
    if metadata:
        combined_metadata.update(metadata)
    return Document(
        document_id=deterministic_document_id(tenant_id, normalized_path),
        tenant_id=tenant_id,
        source_path=normalized_path,
        source_type=source_type,
        content=normalized,
        content_hash=content_sha256(normalized),
        metadata=combined_metadata,
    )


class TextFileLoader:
    _types = {
        ".txt": DocumentSourceType.TEXT,
        ".md": DocumentSourceType.MARKDOWN,
    }

    def load(
        self,
        source_path: Path,
        tenant_id: str,
        metadata: Metadata | None = None,
    ) -> Document:
        suffix = source_path.suffix.lower()
        source_type = self._types.get(suffix)
        if source_type is None:
            raise DocumentLoadError(f"unsupported document type: {suffix or '<none>'}")
        try:
            content = source_path.read_text(encoding="utf-8")
        except UnicodeDecodeError as exc:
            raise DocumentLoadError(f"document is not valid UTF-8: {source_path}") from exc
        except OSError as exc:
            raise DocumentLoadError(f"could not read document {source_path}: {exc}") from exc
        file_metadata: Metadata = {
            "filename": source_path.name,
            "size_bytes": source_path.stat().st_size,
        }
        if metadata:
            file_metadata.update(metadata)
        return document_from_content(
            content=content,
            source_path=str(source_path),
            source_type=source_type,
            tenant_id=tenant_id,
            metadata=file_metadata,
        )

import hashlib
import re
from dataclasses import dataclass
from typing import Protocol

from ctxd.app.models.domain import Chunk, Document, DocumentSourceType

_TOKEN_RE = re.compile(r"\w+|[^\w\s]", re.UNICODE)
_SENTENCE_END_RE = re.compile(r"(?<=[.!?])(?:\s+|$)")


class TokenCounter(Protocol):
    def count(self, text: str) -> int: ...

    def spans(self, text: str) -> list[tuple[int, int]]: ...


class ApproximateTokenCounter:
    """Deterministic word-and-punctuation token approximation."""

    def count(self, text: str) -> int:
        return len(_TOKEN_RE.findall(text))

    def spans(self, text: str) -> list[tuple[int, int]]:
        return [(match.start(), match.end()) for match in _TOKEN_RE.finditer(text)]


@dataclass(frozen=True)
class ChunkingConfig:
    target_tokens: int = 400
    max_tokens: int = 600
    overlap_tokens: int = 40

    def __post_init__(self) -> None:
        if self.target_tokens <= 0:
            raise ValueError("target_tokens must be positive")
        if self.max_tokens < self.target_tokens:
            raise ValueError("max_tokens must be greater than or equal to target_tokens")
        if self.overlap_tokens < 0 or self.overlap_tokens >= self.target_tokens:
            raise ValueError("overlap_tokens must be non-negative and less than target_tokens")


@dataclass(frozen=True)
class _Block:
    content: str
    start_line: int
    end_line: int
    kind: str


def _line_number(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def _make_block(source: str, start: int, end: int, kind: str) -> _Block | None:
    while start < end and source[start].isspace():
        start += 1
    while end > start and source[end - 1].isspace():
        end -= 1
    if start >= end:
        return None
    return _Block(
        content=source[start:end],
        start_line=_line_number(source, start),
        end_line=_line_number(source, max(start, end - 1)),
        kind=kind,
    )


def _plain_blocks(source: str) -> list[_Block]:
    blocks: list[_Block] = []
    start = 0
    for separator in re.finditer(r"\n[ \t]*\n", source):
        block = _make_block(source, start, separator.start(), "paragraph")
        if block:
            blocks.append(block)
        start = separator.end()
    final_block = _make_block(source, start, len(source), "paragraph")
    if final_block:
        blocks.append(final_block)
    return blocks


def _markdown_blocks(source: str) -> list[_Block]:
    lines = source.splitlines(keepends=True)
    offsets: list[int] = []
    position = 0
    for line in lines:
        offsets.append(position)
        position += len(line)

    blocks: list[_Block] = []
    index = 0
    while index < len(lines):
        line = lines[index]
        if not line.strip():
            index += 1
            continue
        start_index = index
        stripped = line.lstrip()
        kind = "paragraph"
        if stripped.startswith("```") or stripped.startswith("~~~"):
            kind = "code"
            fence = stripped[:3]
            index += 1
            while index < len(lines):
                closing = lines[index].lstrip().startswith(fence)
                index += 1
                if closing:
                    break
        elif re.match(r"^#{1,6}\s+", stripped):
            kind = "heading"
            index += 1
        elif re.match(r"^(?:[-*+]\s+|\d+[.)]\s+)", stripped):
            kind = "list"
            index += 1
            while index < len(lines):
                candidate = lines[index]
                if not candidate.strip():
                    break
                if not re.match(r"^\s*(?:[-*+]\s+|\d+[.)]\s+)", candidate):
                    break
                index += 1
        else:
            index += 1
            while index < len(lines) and lines[index].strip():
                candidate = lines[index].lstrip()
                if candidate.startswith(("```", "~~~")) or re.match(
                    r"^(?:#{1,6}\s+|[-*+]\s+|\d+[.)]\s+)", candidate
                ):
                    break
                index += 1
        start = offsets[start_index]
        end = offsets[index] if index < len(offsets) else len(source)
        block = _make_block(source, start, end, kind)
        if block:
            blocks.append(block)
    return blocks


def _split_oversized(
    block: _Block,
    max_tokens: int,
    counter: TokenCounter,
) -> list[_Block]:
    if counter.count(block.content) <= max_tokens:
        return [block]

    # Prefer sentence boundaries before the hard token window.
    boundaries = [match.end() for match in _SENTENCE_END_RE.finditer(block.content)]
    spans = counter.spans(block.content)
    result: list[_Block] = []
    token_start = 0
    while token_start < len(spans):
        token_end = min(token_start + max_tokens, len(spans))
        char_start = spans[token_start][0]
        char_limit = spans[token_end - 1][1]
        preferred = max(
            (boundary for boundary in boundaries if char_start < boundary <= char_limit),
            default=char_limit,
        )
        actual_end = preferred
        included = token_start
        while included < len(spans) and spans[included][1] <= actual_end:
            included += 1
        if included == token_start:
            included = token_end
            actual_end = spans[included - 1][1]
        part = block.content[char_start:actual_end].strip()
        if part:
            prefix = block.content[:char_start]
            result.append(
                _Block(
                    content=part,
                    start_line=block.start_line + prefix.count("\n"),
                    end_line=block.start_line + block.content[:actual_end].count("\n"),
                    kind=block.kind,
                )
            )
        token_start = included
    return result


def deterministic_chunk_id(document: Document, ordinal: int, content: str) -> str:
    digest = hashlib.sha256(
        f"{document.document_id}\0{document.content_hash}\0{ordinal}\0{content}".encode()
    ).hexdigest()
    return f"chk_{digest[:24]}"


class StructureAwareChunker:
    def __init__(
        self,
        config: ChunkingConfig | None = None,
        token_counter: TokenCounter | None = None,
    ) -> None:
        self.config = config or ChunkingConfig()
        self.token_counter = token_counter or ApproximateTokenCounter()

    def chunk(self, document: Document) -> list[Chunk]:
        blocks = (
            _markdown_blocks(document.content)
            if document.source_type == DocumentSourceType.MARKDOWN
            else _plain_blocks(document.content)
        )
        split_blocks = [
            part
            for block in blocks
            for part in _split_oversized(block, self.config.max_tokens, self.token_counter)
        ]
        groups: list[list[_Block]] = []
        index = 0
        while index < len(split_blocks):
            group: list[_Block] = []
            group_tokens = 0
            cursor = index
            while cursor < len(split_blocks):
                block = split_blocks[cursor]
                block_tokens = self.token_counter.count(block.content)
                separator_tokens = 1 if group else 0
                exceeds_target = (
                    group_tokens + separator_tokens + block_tokens > self.config.target_tokens
                )
                if group and exceeds_target:
                    break
                if group_tokens + separator_tokens + block_tokens > self.config.max_tokens:
                    break
                group.append(block)
                group_tokens += separator_tokens + block_tokens
                cursor += 1
            if not group:
                group = [split_blocks[index]]
                cursor = index + 1
            groups.append(group)

            next_index = cursor
            if cursor < len(split_blocks):
                overlap = 0
                for retained_index in range(len(group) - 1, 0, -1):
                    retained_tokens = self.token_counter.count(group[retained_index].content)
                    if overlap + retained_tokens > self.config.overlap_tokens:
                        break
                    overlap += retained_tokens
                    next_index = index + retained_index
            # Always advance; a single large block must not overlap with itself.
            index = max(index + 1, next_index)

        chunks: list[Chunk] = []
        for ordinal, group in enumerate(groups):
            content = "\n\n".join(block.content for block in group).strip()
            if not content:
                continue
            token_count = self.token_counter.count(content)
            if token_count > self.config.max_tokens:
                raise RuntimeError("chunker produced a chunk above the configured hard maximum")
            metadata: dict[str, str | int | float | bool | None | list[str]] = {
                "source_path": document.source_path,
                "content_hash": document.content_hash,
                "block_types": [block.kind for block in group],
            }
            for key, value in document.metadata.items():
                metadata.setdefault(key, value)
            chunks.append(
                Chunk(
                    chunk_id=deterministic_chunk_id(document, ordinal, content),
                    document_id=document.document_id,
                    tenant_id=document.tenant_id,
                    content=content,
                    content_hash=hashlib.sha256(content.encode()).hexdigest(),
                    start_line=group[0].start_line,
                    end_line=group[-1].end_line,
                    token_count=token_count,
                    ordinal=ordinal,
                    metadata=metadata,
                )
            )
        return chunks

from concurrent.futures import ThreadPoolExecutor

from ctxd.app.models.domain import ContextCandidate
from ctxd.app.retrieval.lexical import Retriever
from ctxd.app.retrieval.semantic import SemanticRetriever


class HybridRetriever:
    """Reciprocal-rank fusion preserving both component rankings and scores.

    For each candidate ``d`` this computes exactly
    ``RRF(d) = sum(1 / (k + rank_i(d)))``. Component scores are deliberately
    not normalized or mixed.
    """

    def __init__(
        self,
        lexical: Retriever,
        semantic: SemanticRetriever,
        rrf_k: int = 60,
        candidate_depth: int | None = None,
        parallel: bool = True,
    ) -> None:
        if rrf_k <= 0:
            raise ValueError("rrf_k must be positive")
        if candidate_depth is not None and candidate_depth <= 0:
            raise ValueError("candidate_depth must be positive")
        self.lexical = lexical
        self.semantic = semantic
        self.rrf_k = rrf_k
        self.candidate_depth = candidate_depth
        self.parallel = parallel

    @staticmethod
    def _component_metadata(
        candidate: ContextCandidate, rank: int, component: str
    ) -> dict[str, object]:
        score_key = "raw_lexical_score" if component == "lexical" else "raw_vector_score"
        return {f"{component}_rank": rank, score_key: candidate.relevance_score}

    def fuse(
        self,
        lexical: list[ContextCandidate],
        semantic: list[ContextCandidate],
        top_k: int,
    ) -> list[ContextCandidate]:
        scores: dict[str, float] = {}
        candidates: dict[str, ContextCandidate] = {}
        metadata: dict[str, dict[str, object]] = {}
        for component, results in (("lexical", lexical), ("semantic", semantic)):
            for rank, candidate in enumerate(results, 1):
                item = candidate.source_id
                scores[item] = scores.get(item, 0.0) + 1.0 / (self.rrf_k + rank)
                candidates.setdefault(item, candidate)
                metadata.setdefault(item, {}).update(
                    self._component_metadata(candidate, rank, component)
                )
        # chunk id is the deterministic tie-breaker. Union semantics preserve
        # lexical-only and semantic-only candidates.
        ordered = sorted(scores, key=lambda item: (-scores[item], item))[:top_k]
        return [
            candidates[item].model_copy(
                update={
                    "relevance_score": scores[item],
                    "metadata": {
                        **candidates[item].metadata,
                        **metadata[item],
                        "fused_score": scores[item],
                    },
                }
            )
            for item in ordered
        ]

    def search(self, query: str, tenant_id: str, top_k: int) -> list[ContextCandidate]:
        if top_k <= 0:
            raise ValueError("top_k must be positive")
        width = self.candidate_depth or max(top_k, min(100, top_k * 2))
        if self.parallel:
            with ThreadPoolExecutor(max_workers=2, thread_name_prefix="ctxd-hybrid") as executor:
                lexical_future = executor.submit(self.lexical.search, query, tenant_id, width)
                semantic_future = executor.submit(self.semantic.search, query, tenant_id, width)
                lexical = lexical_future.result()
                semantic = semantic_future.result()
        else:
            lexical = self.lexical.search(query, tenant_id, width)
            semantic = self.semantic.search(query, tenant_id, width)
        return self.fuse(lexical, semantic, top_k)

import math
from collections import Counter
from collections.abc import Sequence
from threading import RLock
from typing import Protocol

from ctxd.app.models.domain import Chunk, Document, LexicalIndexStatistics, SemanticIndexStatistics
