class InMemoryDocumentStore:
    """Thread-safe document store with an incrementally maintained BM25 index."""

    def __init__(self) -> None:
        self._documents: dict[tuple[str, str], Document] = {}
        self._chunks: dict[tuple[str, str], Chunk] = {}
        self._terms_by_chunk: dict[tuple[str, str], Counter[str]] = {}
        self._postings: dict[tuple[str, str], dict[str, int]] = {}
        self._document_frequency: Counter[tuple[str, str]] = Counter()
        self._chunk_count: Counter[str] = Counter()
        self._total_lexical_length: Counter[str] = Counter()
        self._embeddings: dict[tuple[str, str], tuple[str, list[float]]] = {}
        self._lock = RLock()

    @staticmethod
    def _validate_chunks(document_id: str, tenant_id: str, chunks: Sequence[Chunk]) -> None:
        if any(
            chunk.document_id != document_id or chunk.tenant_id != tenant_id for chunk in chunks
        ):
            raise ValueError("all chunks must belong to the requested document and tenant")

    def replace_document(
        self,
        document: Document,
        chunks: Sequence[Chunk],
        *,
        embedding_version: str | None = None,
        embeddings: dict[str, list[float]] | None = None,
    ) -> bool:
        self._validate_chunks(document.document_id, document.tenant_id, chunks)
        key = (document.tenant_id, document.document_id)
        with self._lock:
            previous = self._documents.get(key)
            if previous is not None and previous.content_hash == document.content_hash:
                return False
            self._documents[key] = document.model_copy(deep=True)
            self._replace_chunks_locked(document.document_id, document.tenant_id, chunks)
            if embedding_version and embeddings is not None:
                for chunk in chunks:
                    self._embeddings[(document.tenant_id, chunk.chunk_id)] = (
                        embedding_version,
                        list(embeddings[chunk.chunk_id]),
                    )
            return previous is None

    def upsert_document(self, document: Document) -> bool:
        return self.replace_document(document, [])

    def replace_chunks(
        self,
        document_id: str,
        tenant_id: str,
        chunks: Sequence[Chunk],
    ) -> None:
        self._validate_chunks(document_id, tenant_id, chunks)
        with self._lock:
            if (tenant_id, document_id) not in self._documents:
                raise KeyError(f"document not found for tenant: {document_id}")
            self._replace_chunks_locked(document_id, tenant_id, chunks)

    def _remove_chunk_locked(self, tenant_id: str, chunk_id: str) -> None:
        key = (tenant_id, chunk_id)
        terms = self._terms_by_chunk.pop(key, Counter())
        for term in terms:
            postings_key = (tenant_id, term)
            postings = self._postings[postings_key]
            postings.pop(chunk_id, None)
            self._document_frequency[postings_key] -= 1
            if not postings:
                del self._postings[postings_key]
                del self._document_frequency[postings_key]
        self._chunk_count[tenant_id] -= 1
        self._total_lexical_length[tenant_id] -= sum(terms.values())
        self._chunks.pop(key, None)

    def _replace_chunks_locked(
        self,
        document_id: str,
        tenant_id: str,
        chunks: Sequence[Chunk],
    ) -> None:
        stale_ids = [
            chunk.chunk_id
            for (owner, _), chunk in self._chunks.items()
            if owner == tenant_id and chunk.document_id == document_id
        ]
        for chunk_id in stale_ids:
            self._remove_chunk_locked(tenant_id, chunk_id)
            self._embeddings.pop((tenant_id, chunk_id), None)

        for chunk in chunks:
            chunk_copy = chunk.model_copy(deep=True)
            key = (tenant_id, chunk.chunk_id)
            terms = Counter(tokenize_lexical(chunk.content))
            self._chunks[key] = chunk_copy
            self._terms_by_chunk[key] = terms
            self._chunk_count[tenant_id] += 1
            self._total_lexical_length[tenant_id] += sum(terms.values())
            for term, frequency in terms.items():
                postings_key = (tenant_id, term)
                self._postings.setdefault(postings_key, {})[chunk.chunk_id] = frequency
                self._document_frequency[postings_key] += 1

    def get_document(self, document_id: str, tenant_id: str) -> Document | None:
        with self._lock:
            document = self._documents.get((tenant_id, document_id))
            return document.model_copy(deep=True) if document else None

    def get_chunk(self, chunk_id: str, tenant_id: str) -> Chunk | None:
        with self._lock:
            chunk = self._chunks.get((tenant_id, chunk_id))
            return chunk.model_copy(deep=True) if chunk else None

    def list_chunks(self, tenant_id: str, document_id: str | None = None) -> list[Chunk]:
        with self._lock:
            chunks = [
                chunk.model_copy(deep=True)
                for (owner, _), chunk in self._chunks.items()
                if owner == tenant_id and (document_id is None or chunk.document_id == document_id)
            ]
        return sorted(chunks, key=lambda chunk: (chunk.document_id, chunk.ordinal, chunk.chunk_id))

    def delete_document(self, document_id: str, tenant_id: str) -> bool:
        with self._lock:
            removed = self._documents.pop((tenant_id, document_id), None)
            stale_ids = [
                chunk.chunk_id
                for (owner, _), chunk in self._chunks.items()
                if owner == tenant_id and chunk.document_id == document_id
            ]
            for chunk_id in stale_ids:
                self._remove_chunk_locked(tenant_id, chunk_id)
                self._embeddings.pop((tenant_id, chunk_id), None)
            return removed is not None

    def search_semantic(
        self, query_vector: list[float], tenant_id: str, top_k: int, *, version: str
    ) -> list[SemanticHit]:
        with self._lock:
            scored: list[tuple[float, str]] = []
            for (owner, chunk_id), (stored_version, vector) in self._embeddings.items():
                if owner != tenant_id or stored_version != version:
                    continue
                score = sum(a * b for a, b in zip(query_vector, vector, strict=False))
                scored.append((score, chunk_id))
            scored.sort(key=lambda item: (-item[0], item[1]))
            return [
                SemanticHit(self._chunks[(tenant_id, chunk_id)].model_copy(deep=True), score)
                for score, chunk_id in scored[:top_k]
            ]

    def semantic_statistics(self, tenant_id: str) -> SemanticIndexStatistics:
        with self._lock:
            versions = [
                version
                for (owner, _), (version, _) in self._embeddings.items()
                if owner == tenant_id
            ]
            dimension = len(
                next(
                    (
                        vector
                        for (owner, _), (_, vector) in self._embeddings.items()
                        if owner == tenant_id
                    ),
                    [],
                )
            )
            return SemanticIndexStatistics(
                indexed_chunks=len(versions),
                embedding_version=versions[0] if versions else "",
                embedding_dimension=dimension or 1,
            )

    def search_lexical(
        self,
        query: str,
        tenant_id: str,
        top_k: int,
        *,
        k1: float,
        b: float,
    ) -> list[LexicalHit]:
        query_frequency = Counter(tokenize_lexical(query))
        if not query_frequency:
            return []
        with self._lock:
            corpus_size = self._chunk_count[tenant_id]
            if corpus_size == 0:
                return []
            average_length = self._total_lexical_length[tenant_id] / corpus_size
            candidate_ids: set[str] = set()
            for term in query_frequency:
                candidate_ids.update(self._postings.get((tenant_id, term), {}))

            scored: list[tuple[float, str]] = []
            for chunk_id in candidate_ids:
                terms = self._terms_by_chunk[(tenant_id, chunk_id)]
                length_normalization = 1 - b + b * sum(terms.values()) / max(average_length, 1.0)
                score = 0.0
                for term, query_count in query_frequency.items():
                    frequency = terms.get(term, 0)
                    if frequency == 0:
                        continue
                    df = self._document_frequency[(tenant_id, term)]
                    inverse_document_frequency = math.log(1 + (corpus_size - df + 0.5) / (df + 0.5))
                    score += (
                        inverse_document_frequency
                        * (frequency * (k1 + 1) / (frequency + k1 * length_normalization))
                        * query_count
                    )
                if score > 0:
                    scored.append((score, chunk_id))
            scored.sort(key=lambda item: (-item[0], item[1]))
            return [
                LexicalHit(
                    chunk=self._chunks[(tenant_id, chunk_id)].model_copy(deep=True),
                    score=score,
                )
                for score, chunk_id in scored[:top_k]
            ]

    def lexical_statistics(self, tenant_id: str) -> LexicalIndexStatistics:
        with self._lock:
            chunk_count = self._chunk_count[tenant_id]
            document_count = sum(owner == tenant_id for owner, _ in self._documents)
            vocabulary_size = sum(owner == tenant_id for owner, _ in self._postings)
            average_length = (
                self._total_lexical_length[tenant_id] / chunk_count if chunk_count else 0.0
            )
            return LexicalIndexStatistics(
                indexed_documents=document_count,
                indexed_chunks=chunk_count,
                vocabulary_size=vocabulary_size,
                average_chunk_length=average_length,
            )

from __future__ import annotations

import math
from typing import Protocol

from ctxd.app.models.domain import ContextCandidate


class Reranker(Protocol):
    model_id: str

    def rerank(
        self, query: str, candidates: list[ContextCandidate], top_k: int
    ) -> list[ContextCandidate]: ...


def apply_scores(
    candidates: list[ContextCandidate],
    scores: list[float],
    *,
    top_k: int,
    model_id: str,
) -> list[ContextCandidate]:
    if top_k <= 0:
        raise ValueError("top_k must be positive")
    if len(scores) != len(candidates):
        raise ValueError("reranker score count does not match candidate count")
    if any(not math.isfinite(score) for score in scores):
        raise ValueError("reranker scores must be finite")
    ranked = sorted(
        enumerate(zip(candidates, scores, strict=True)),
        key=lambda item: (-item[1][1], item[0]),
    )
    return [
        candidate.model_copy(
            update={
                "rerank_score": max(0.0, score),
                "metadata": {
                    **candidate.metadata,
                    "reranker_score": score,
                    "pre_rerank_rank": original_index + 1,
                    "reranked_rank": reranked_index,
                    "reranker_model": model_id,
                },
            }
        )
        for reranked_index, (original_index, (candidate, score)) in enumerate(ranked[:top_k], 1)
    ]

from __future__ import annotations

from opentelemetry import trace

from ctxd.app.models.domain import ContextCandidate
from ctxd.app.observability.metrics import RERANKER_REQUESTS_TOTAL
from ctxd.app.reranking.base import Reranker
from ctxd.app.retrieval.lexical import Retriever

tracer = trace.get_tracer(__name__)


class RerankingRetriever:
    """Reorder a fixed upstream candidate set, falling back to its original order."""

    def __init__(
        self, upstream: Retriever, reranker: Reranker, *, candidate_count: int = 20
    ) -> None:
        if candidate_count <= 0:
            raise ValueError("candidate_count must be positive")
        self.upstream = upstream
        self.reranker = reranker
        self.candidate_count = candidate_count

    def search(self, query: str, tenant_id: str, top_k: int) -> list[ContextCandidate]:
        if top_k <= 0:
            raise ValueError("top_k must be positive")
        candidates = self.upstream.search(query, tenant_id, self.candidate_count)
        if not candidates:
            return []
        with tracer.start_as_current_span("retrieval.rerank") as span:
            span.set_attribute("reranker.model", self.reranker.model_id)
            span.set_attribute("reranker.candidate_count", len(candidates))
            try:
                reranked = self.reranker.rerank(query, candidates, top_k)
                if not self._same_candidate_set(candidates, reranked, top_k):
                    raise ValueError("reranker changed the candidate set")
                span.set_attribute("reranker.result_count", len(reranked))
                RERANKER_REQUESTS_TOTAL.labels(self.reranker.model_id, "success").inc()
                return reranked
            except Exception:
                RERANKER_REQUESTS_TOTAL.labels(self.reranker.model_id, "fallback").inc()
                return candidates[:top_k]

    @staticmethod
    def _same_candidate_set(
        original: list[ContextCandidate], reranked: list[ContextCandidate], top_k: int
    ) -> bool:
        original_ids = {candidate.source_id for candidate in original}
        reranked_ids = [candidate.source_id for candidate in reranked]
        return (
            len(reranked_ids) == min(len(original), top_k)
            and len(reranked_ids) == len(set(reranked_ids))
            and set(reranked_ids) <= original_ids
        )

from collections import Counter
from collections.abc import Iterable, Mapping
from typing import Any, Literal, cast

from ctxd.app.integrations.synapse.schemas import (
    McpInvocationResult,
    McpToolSchema,
    SynapseEvalCase,
    SynapseEvalReport,
    SynapseEvalResult,
    SynapseFailureCategory,
)


def _percentile(values: list[float], percentile: float) -> float:
    if not values:
        return 0.0
    ordered = sorted(values)
    index = int(round((len(ordered) - 1) * percentile))
    return ordered[index]


def _json_type_matches(value: Any, json_type: str) -> bool:
    if json_type == "string":
        return isinstance(value, str)
    if json_type == "number":
        return isinstance(value, int | float) and not isinstance(value, bool)
    if json_type == "integer":
        return isinstance(value, int) and not isinstance(value, bool)
    if json_type == "boolean":
        return isinstance(value, bool)
    if json_type == "array":
        return isinstance(value, list)
    if json_type == "object":
        return isinstance(value, dict)
    return True


def validate_arguments(schema: McpToolSchema | None, arguments: Mapping[str, Any] | None) -> bool:
    if schema is None or arguments is None:
        return False
    input_schema = schema.input_schema
    required = input_schema.get("required", [])
    if not isinstance(required, list):
        return False
    for key in required:
        if not isinstance(key, str) or key not in arguments:
            return False
    properties = input_schema.get("properties", {})
    if not isinstance(properties, dict):
        return False
    for key, value in arguments.items():
        definition = properties.get(key)
        if (
            isinstance(definition, dict)
            and isinstance(definition.get("type"), str)
            and not _json_type_matches(value, definition["type"])
        ):
            return False
    return True


def _tool_correct(case: SynapseEvalCase, selected_tool: str | None) -> bool:
    acceptable = set(case.acceptable_tools)
    if case.expected_tool is not None:
        acceptable.add(case.expected_tool)
    return selected_tool is not None and selected_tool in acceptable


def _arguments_match(expected: Mapping[str, Any], actual: Mapping[str, Any] | None) -> bool:
    if actual is None:
        return False
    return all(actual.get(key) == value for key, value in expected.items())


def _output_status(case: SynapseEvalCase, invocation: McpInvocationResult) -> str:
    if case.expected_outcome is None:
        return "not_checked"
    return "match" if invocation.output == case.expected_outcome else "mismatch"


def evaluate_cases(
    cases: Iterable[SynapseEvalCase],
    invocations: Mapping[str, McpInvocationResult],
    tool_schemas: Iterable[McpToolSchema],
    *,
    synthetic: bool = True,
) -> SynapseEvalReport:
    schema_by_name = {schema.name: schema for schema in tool_schemas}
    results: list[SynapseEvalResult] = []
    failures: Counter[str] = Counter()
    for case in cases:
        invocation = invocations[case.id]
        schema = schema_by_name.get(invocation.selected_tool or "")
        schema_valid = validate_arguments(schema, invocation.arguments)
        tool_correct = _tool_correct(case, invocation.selected_tool)
        arguments_valid = schema_valid and _arguments_match(
            case.expected_arguments, invocation.arguments
        )
        output_status = _output_status(case, invocation)
        task_success = (
            tool_correct
            and arguments_valid
            and invocation.execution_success
            and output_status != "mismatch"
        )
        category = invocation.error_category
        if category is None and not tool_correct:
            category = SynapseFailureCategory.WRONG_TOOL
        elif category is None and not schema_valid:
            category = SynapseFailureCategory.SCHEMA_VIOLATION
        elif category is None and not arguments_valid:
            category = SynapseFailureCategory.MALFORMED_ARGUMENTS
        elif category is None and not invocation.execution_success:
            category = SynapseFailureCategory.EXECUTION_ERROR
        elif category is None and invocation.execution_success and output_status == "mismatch":
            category = SynapseFailureCategory.INCORRECT_OUTPUT
        if category is not None and not task_success:
            failures[category.value] += 1
        results.append(
            SynapseEvalResult(
                case_id=case.id,
                selected_tool=invocation.selected_tool,
                tool_selection_correct=tool_correct,
                argument_validity=arguments_valid,
                schema_validity=schema_valid,
                execution_success=invocation.execution_success,
                task_success=task_success,
                retry_count=invocation.retry_count,
                latency_ms=invocation.latency_ms,
                error_category=category if not task_success else None,
                output_match_status=cast(
                    "Literal['match', 'mismatch', 'not_checked']", output_status
                ),
                metadata={**case.metadata, **invocation.metadata},
            )
        )
    count = len(results)
    denominator = max(count, 1)
    latencies = [result.latency_ms for result in results]
    return SynapseEvalReport(
        synthetic=synthetic,
        case_count=count,
        tool_selection_accuracy=sum(r.tool_selection_correct for r in results) / denominator,
        schema_validity_rate=sum(r.schema_validity for r in results) / denominator,
        argument_validity_rate=sum(r.argument_validity for r in results) / denominator,
        task_success_rate=sum(r.task_success for r in results) / denominator,
        execution_success_rate=sum(r.execution_success for r in results) / denominator,
        retry_rate=sum(r.retry_count > 0 for r in results) / denominator,
        p50_latency_ms=_percentile(latencies, 0.50),
        p95_latency_ms=_percentile(latencies, 0.95),
        p99_latency_ms=_percentile(latencies, 0.99),
        failure_counts=dict(sorted(failures.items())),
        results=results,
    )

"""Offline, exact-span evidence evaluation; never imported by production retrieval."""

from __future__ import annotations

import hashlib
import json
import random
from collections import defaultdict
from collections.abc import Mapping, Sequence
from typing import Literal, Self

from pydantic import BaseModel, ConfigDict, Field, model_validator

from ctxd.app.evals.context_selection import SelectionCandidate, validate_candidates
from ctxd.app.evals.retrieval import ndcg_at_k, recall_at_k, reciprocal_rank
from ctxd.app.ingestion.chunking import ApproximateTokenCounter, StructureAwareChunker
from ctxd.app.models.domain import Chunk, Document


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid")


class EvidenceSpan(StrictModel):
    source: str
    chunk_id: str
    start: int = Field(ge=0)
    end: int = Field(gt=0)
    excerpt: str = Field(min_length=1)

    @model_validator(mode="after")
    def valid_range(self) -> Self:
        if self.end <= self.start:
            raise ValueError("span must be nonempty, half-open character offsets")
        return self


class EvidenceAlternative(StrictModel):
    # Every span in ONE alternative must survive; alternatives are interchangeable.
    spans: list[EvidenceSpan] = Field(min_length=1)


class EvidenceGroup(StrictModel):
    group_id: str
    requirement: Literal["REQUIRED", "SUPPORTING", "OPTIONAL"]
    alternatives: list[EvidenceAlternative] = Field(min_length=1)


class EvidenceCase(StrictModel):
    case_id: str
    query: str = Field(min_length=1)
    tenant_id: str
    template_group: str
    evidence_groups: list[EvidenceGroup] = Field(default_factory=list)
    status: Literal["VERIFIED_FIXTURE", "NEEDS_HUMAN_REVIEW"]
    answerability_notes: str
    budget_pressure_class: str

    @model_validator(mode="after")
    def group_contract(self) -> Self:
        ids = [g.group_id for g in self.evidence_groups]
        if len(ids) != len(set(ids)):
            raise ValueError("duplicate group ID")
        if self.status != "NEEDS_HUMAN_REVIEW" and not any(
            g.requirement == "REQUIRED" for g in self.evidence_groups
        ):
            raise ValueError("at least one required group; no vacuous answerability")
        return self


class EvidenceCorpus(StrictModel):
    provenance: str
    documents: list[Document]
    chunks: list[Chunk]
    cases: list[EvidenceCase]

    @model_validator(mode="after")
    def validate_locators(self) -> Self:
        chunks = {c.chunk_id: c for c in self.chunks}
        if len(chunks) != len(self.chunks):
            raise ValueError("duplicate chunk identity")
        regenerated = [c for d in self.documents for c in StructureAwareChunker().chunk(d)]
        if {c.chunk_id: c for c in regenerated} != chunks:
            raise ValueError("chunks do not match production chunking of corpus documents")
        if len({c.case_id for c in self.cases}) != len(self.cases):
            raise ValueError("duplicate case ID")
        document_keys = [(d.tenant_id, d.source_path) for d in self.documents]
        if len(set(document_keys)) != len(document_keys):
            raise ValueError("duplicate tenant/source document")
        for case in self.cases:
            for group in case.evidence_groups:
                for alternative in group.alternatives:
                    for span in alternative.spans:
                        chunk = chunks.get(span.chunk_id)
                        if chunk is None or chunk.tenant_id != case.tenant_id:
                            raise ValueError("unknown or cross-tenant evidence chunk")
                        if chunk.metadata["source_path"] != span.source:
                            raise ValueError("source locator mismatch")
                        if (
                            span.end > len(chunk.content)
                            or chunk.content[span.start : span.end] != span.excerpt
                        ):
                            raise ValueError("evidence span does not match corpus text")
        return self


def digest(value: object) -> str:
    return hashlib.sha256(
        json.dumps(value, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()


def grouped_split(cases: Sequence[EvidenceCase], seed: int) -> dict[str, str]:
    groups = sorted({c.template_group for c in cases})
    if len(groups) < 3:
        raise ValueError("need at least three template groups")
    random.Random(seed).shuffle(groups)
    holdout = set(groups[: max(1, len(groups) // 3)])
    result = {c.case_id: "holdout" if c.template_group in holdout else "development" for c in cases}
    validate_split(cases, result)
    return result


def validate_split(cases: Sequence[EvidenceCase], assignments: Mapping[str, str]) -> None:
    if set(assignments) != {c.case_id for c in cases}:
        raise ValueError("split case identities differ")
    groups: dict[str, set[str]] = defaultdict(set)
    queries: dict[str, set[str]] = defaultdict(set)
    sources: dict[tuple[str, str], set[str]] = defaultdict(set)
    for case in cases:
        partition = assignments[case.case_id]
        if partition not in {"development", "holdout"}:
            raise ValueError("unknown partition")
        groups[case.template_group].add(partition)
        queries[" ".join(case.query.casefold().split())].add(partition)
        for group in case.evidence_groups:
            for alternative in group.alternatives:
                for span in alternative.spans:
                    sources[case.tenant_id, span.source].add(partition)
    if any(len(v) > 1 for v in [*groups.values(), *queries.values(), *sources.values()]):
        raise ValueError("template, duplicate-query or evidence-source leakage")


def evaluate_evidence(
    case: EvidenceCase,
    retrieved: Sequence[SelectionCandidate],
    selected: Sequence[SelectionCandidate],
    chunks: Mapping[str, Chunk],
) -> dict[str, float]:
    """CTXD metrics use production approximate tokens, not model/BPE tokens.

    Precision counts the union of labeled span tokens. Redundancy counts labeled
    span tokens beyond the cheapest complete alternative per group; it does not
    infer semantic redundancy in unlabeled prose. Distractor tokens belong to
    chunks with no labeled span. These fractions are not a disjoint partition.
    """
    if case.status != "VERIFIED_FIXTURE":
        raise ValueError("unreviewed case cannot receive an answerability score")
    validate_candidates(retrieved)
    validate_candidates(selected)
    original = {c.identity: c for c in retrieved}
    if any(original.get(c.identity) != c for c in selected):
        raise ValueError("selection changed candidates")
    for candidate in retrieved:
        chunk = chunks[candidate.identity]
        if (
            chunk.tenant_id != case.tenant_id
            or candidate.content != chunk.content
            or candidate.tokens != chunk.token_count
            or candidate.source != chunk.metadata["source_path"]
        ):
            raise ValueError("candidate provenance or tenant mismatch")
    counter = ApproximateTokenCounter()
    selected_ids = {c.identity for c in selected}
    retrieved_ids = set(original)
    covered: dict[str, bool] = {}
    retrieved_covered: dict[str, bool] = {}
    labeled: set[tuple[str, int]] = set()
    necessary: set[tuple[str, int]] = set()
    relevant_chunks: set[str] = set()
    required_chunks: set[str] = set()
    for group in case.evidence_groups:
        covered[group.group_id] = False
        retrieved_covered[group.group_id] = False
        complete: list[set[tuple[str, int]]] = []
        group_labeled: set[tuple[str, int]] = set()
        for alternative in group.alternatives:
            ids = {s.chunk_id for s in alternative.spans}
            relevant_chunks.update(ids)
            if group.requirement == "REQUIRED":
                required_chunks.update(ids)
            retrieved_covered[group.group_id] |= ids <= retrieved_ids
            all_tokens: set[tuple[str, int]] = set()
            for span in alternative.spans:
                chunk = chunks[span.chunk_id]
                # Recheck at evaluation boundary; annotations may not have come from Corpus.
                if (
                    chunk.tenant_id != case.tenant_id
                    or chunk.metadata["source_path"] != span.source
                    or span.end > len(chunk.content)
                    or chunk.content[span.start : span.end] != span.excerpt
                ):
                    raise ValueError("span drift or provenance mismatch")
                all_tokens.update(
                    (span.chunk_id, i)
                    for i, (start, end) in enumerate(counter.spans(chunk.content))
                    if start < span.end and end > span.start
                )
            group_labeled.update(t for t in all_tokens if t[0] in selected_ids)
            if ids <= selected_ids:
                covered[group.group_id] = True
                complete.append(all_tokens)
        labeled.update(group_labeled)
        if complete:
            cheapest = sorted(complete, key=lambda s: (len(s), sorted(s)))[0]
            necessary.update(cheapest)
        else:
            # Partial evidence is useful progress, not redundant solely for being incomplete.
            necessary.update(group_labeled)
    required = [g.group_id for g in case.evidence_groups if g.requirement == "REQUIRED"]
    supporting = [g.group_id for g in case.evidence_groups if g.requirement == "SUPPORTING"]
    total = sum(c.tokens for c in selected)
    paths = [c.identity for c in selected]
    result = {
        "required_recall": sum(covered[g] for g in required) / len(required),
        "full_answerability": float(all(covered[g] for g in required)),
        "supporting_recall": sum(covered[g] for g in supporting) / len(supporting)
        if supporting
        else 0.0,
        "supporting_applicable": float(bool(supporting)),
        "retrieved_required_recall": sum(retrieved_covered[g] for g in required) / len(required),
        "selected_tokens": float(total),
        "span_token_precision": len(labeled) / total if total else 0.0,
        "redundant_span_tokens": float(len(labeled - necessary)),
        "redundant_token_fraction": len(labeled - necessary) / total if total else 0.0,
        "distractor_tokens": float(
            sum(c.tokens for c in selected if c.identity not in relevant_chunks)
        ),
        "required_groups_per_1k_tokens": sum(covered[g] for g in required) * 1000 / total
        if total
        else 0.0,
        "selected_count": float(len(selected)),
        "mrr": reciprocal_rank(paths, required_chunks),
        "ndcg_at_5": ndcg_at_k(paths, required_chunks, 5),
        "ndcg_at_10": ndcg_at_k(paths, required_chunks, 10),
    }
    result["distractor_token_fraction"] = result["distractor_tokens"] / total if total else 0.0
    for k in (1, 5, 10):
        result[f"recall_at_{k}"] = recall_at_k(paths, required_chunks, k)
    return result


def clustered_bootstrap(
    deltas: Mapping[str, Sequence[float]], seed: int = 902026, resamples: int = 2000
) -> dict[str, float]:
    """Resample whole template groups; return case-weighted mean delta interval."""
    if not deltas or any(not values for values in deltas.values()) or resamples < 2000:
        raise ValueError("nonempty clusters and >=2000 resamples required")
    groups = sorted(deltas)
    rng = random.Random(seed)
    samples = []
    for _ in range(resamples):
        values = [v for _ in groups for v in deltas[rng.choice(groups)]]
        samples.append(sum(values) / len(values))
    samples.sort()
    values = [v for g in groups for v in deltas[g]]
    return {
        "point": sum(values) / len(values),
        "low": samples[int(0.025 * (resamples - 1))],
        "high": samples[int(0.975 * (resamples - 1))],
        "clusters": float(len(groups)),
        "resamples": float(resamples),
    }

import argparse
import json
import math
from pathlib import Path
from typing import Any, Protocol

from ctxd.app.evals.schemas import (
    RetrievalEvalCorpus,
    RetrievalEvalResult,
    RetrievalMetrics,
    RetrievalModeEvalResult,
)
from ctxd.app.ingestion.chunking import ChunkingConfig, StructureAwareChunker
from ctxd.app.ingestion.service import IngestionService
from ctxd.app.models.domain import ContextCandidate
from ctxd.app.retrieval.hybrid import HybridRetriever
from ctxd.app.retrieval.lexical import BM25Retriever
from ctxd.app.retrieval.semantic import (
    EmbeddingModel,
    FakeHashEmbeddingProvider,
    RealEmbeddingProvider,
    SemanticRetriever,
)
from ctxd.app.runtime import CorpusBackend
from ctxd.app.storage.documents import InMemoryDocumentStore
from ctxd.app.storage.postgres import PostgresDocumentStore


class Searcher(Protocol):
    def search(self, query: str, tenant_id: str, top_k: int) -> list[ContextCandidate]: ...


def recall_at_k(retrieved: list[str], relevant: set[str], k: int) -> float:
    if not relevant:
        return 0.0
    return len(set(retrieved[:k]) & relevant) / len(relevant)


def reciprocal_rank(retrieved: list[str], relevant: set[str]) -> float:
    for rank, source in enumerate(retrieved, start=1):
        if source in relevant:
            return 1.0 / rank
    return 0.0


def ndcg_at_k(retrieved: list[str], relevant: set[str], k: int) -> float:
    if not relevant:
        return 0.0
    # Judgments identify sources, not chunks. Repeated chunks consume rank positions
    # but must not earn a second gain for the same judged source.
    seen: set[str] = set()
    dcg = 0.0
    for rank, source in enumerate(retrieved[:k], start=1):
        if source in relevant and source not in seen:
            dcg += 1.0 / math.log2(rank + 1)
        seen.add(source)
    ideal_count = min(k, len(relevant))
    ideal_dcg = sum(1.0 / math.log2(rank + 1) for rank in range(1, ideal_count + 1))
    return dcg / ideal_dcg


def _metrics(rows: list[tuple[list[str], set[str]]]) -> RetrievalMetrics:
    denominator = max(len(rows), 1)
    return RetrievalMetrics(
        recall_at_1=sum(recall_at_k(got, expected, 1) for got, expected in rows) / denominator,
        recall_at_5=sum(recall_at_k(got, expected, 5) for got, expected in rows) / denominator,
        recall_at_10=sum(recall_at_k(got, expected, 10) for got, expected in rows) / denominator,
        mrr=sum(reciprocal_rank(got, expected) for got, expected in rows) / denominator,
        ndcg_at_5=sum(ndcg_at_k(got, expected, 5) for got, expected in rows) / denominator,
        ndcg_at_10=sum(ndcg_at_k(got, expected, 10) for got, expected in rows) / denominator,
    )


def _result_rows(candidates: list[ContextCandidate]) -> list[dict[str, Any]]:
    return [
        {
            "source": candidate.metadata.get("source_path"),
            "chunk_id": candidate.source_id,
            "score": candidate.relevance_score,
            "lexical_rank": candidate.metadata.get("lexical_rank"),
            "semantic_rank": candidate.metadata.get("semantic_rank"),
            "raw_lexical_score": candidate.metadata.get("raw_lexical_score"),
            "raw_vector_score": candidate.metadata.get("raw_vector_score"),
            "fused_score": candidate.metadata.get("fused_score"),
        }
        for candidate in candidates
    ]


def _rank(paths: list[str], expected: set[str]) -> int | None:
    return next((rank for rank, path in enumerate(paths, 1) if path in expected), None)


def _classify_failure(
    lexical_rank: int | None, semantic_rank: int | None, hybrid_rank: int | None, category: str
) -> str:
    if category == "ambiguous":
        return "annotation ambiguity"
    if category == "near duplicate":
        return "near-duplicate confusion"
    if lexical_rank is None and semantic_rank is not None:
        return "lexical mismatch"
    if semantic_rank is None and lexical_rank is not None:
        return "semantic miss"
    if semantic_rank is not None and semantic_rank > 1:
        return "semantic overgeneralization"
    if hybrid_rank is None and (lexical_rank is not None or semantic_rank is not None):
        return "fusion demotion"
    if lexical_rank is None and semantic_rank is None:
        return "insufficient candidate depth"
    return "other"


def run_mode_evaluation(
    corpus: RetrievalEvalCorpus,
    store: CorpusBackend | None = None,
    embedding_model: EmbeddingModel | None = None,
    *,
    candidate_depth: int = 20,
    rrf_k: int = 60,
    parallel_hybrid: bool = True,
) -> RetrievalModeEvalResult:
    resolved_store = store or InMemoryDocumentStore()
    model = embedding_model or FakeHashEmbeddingProvider()
    ingestion = IngestionService(
        resolved_store,
        StructureAwareChunker(ChunkingConfig(target_tokens=80, max_tokens=120, overlap_tokens=10)),
        model,
    )
    for document in corpus.documents:
        ingestion.ingest_content(
            content=document.content,
            source_path=document.source_path,
            source_type=document.source_type,
            tenant_id=document.tenant_id,
            metadata=document.metadata,
        )

    lexical = BM25Retriever(resolved_store)
    semantic = SemanticRetriever(resolved_store, model)
    retrievers: dict[str, Searcher] = {
        "lexical": lexical,
        "semantic": semantic,
        "hybrid": HybridRetriever(
            lexical,
            semantic,
            rrf_k=rrf_k,
            candidate_depth=candidate_depth,
            parallel=parallel_hybrid,
        ),
    }
    observations: dict[str, list[tuple[list[str], set[str]]]] = {
        mode: [] for mode in retrievers
    }
    category_observations: dict[str, dict[str, list[tuple[list[str], set[str]]]]] = {}
    failures: list[dict[str, Any]] = []

    for case in corpus.cases:
        expected = set(case.expected_sources)
        category = str(case.metadata.get("category", case.task_type)).replace("_", " ")
        category_rows = category_observations.setdefault(
            category, {mode: [] for mode in retrievers}
        )
        result_by_mode: dict[str, list[ContextCandidate]] = {}
        paths_by_mode: dict[str, list[str]] = {}
        for mode, retriever in retrievers.items():
            candidates = retriever.search(case.question, case.tenant_id, 10)
            paths = [str(candidate.metadata["source_path"]) for candidate in candidates]
            result_by_mode[mode] = candidates
            paths_by_mode[mode] = paths
            row = (paths, expected)
            observations[mode].append(row)
            category_rows[mode].append(row)
        ranks = {mode: _rank(paths, expected) for mode, paths in paths_by_mode.items()}
        if any(rank != 1 for rank in ranks.values()):
            failures.append(
                {
                    "case_id": case.id,
                    "category": category,
                    "expected_sources": sorted(expected),
                    "lexical_top_results": _result_rows(result_by_mode["lexical"]),
                    "semantic_top_results": _result_rows(result_by_mode["semantic"]),
                    "hybrid_top_results": _result_rows(result_by_mode["hybrid"]),
                    "lexical_rank": ranks["lexical"],
                    "semantic_rank": ranks["semantic"],
                    "hybrid_rank": ranks["hybrid"],
                    "failure_class": _classify_failure(
                        ranks["lexical"], ranks["semantic"], ranks["hybrid"], category
                    ),
                }
            )

    return RetrievalModeEvalResult(
        case_count=len(corpus.cases),
        model_version=model.version,
        modes={mode: _metrics(rows) for mode, rows in observations.items()},
        categories={
            category: {mode: _metrics(rows) for mode, rows in modes.items()}
            for category, modes in category_observations.items()
        },
        failures=failures,
    )


def run_retrieval_eval(
    corpus: RetrievalEvalCorpus,
    store: CorpusBackend | None = None,
) -> RetrievalEvalResult:
    """Preserved Phase 3 lexical evaluator and output contract."""
    resolved_store = store or InMemoryDocumentStore()
    ingestion = IngestionService(
        resolved_store,
        StructureAwareChunker(ChunkingConfig(target_tokens=80, max_tokens=120, overlap_tokens=10)),
    )
    for document in corpus.documents:
        ingestion.ingest_content(
            content=document.content,
            source_path=document.source_path,
            source_type=document.source_type,
            tenant_id=document.tenant_id,
            metadata=document.metadata,
        )
    retriever = BM25Retriever(resolved_store)
    per_case: dict[str, dict[str, float]] = {}
    rows: list[tuple[list[str], set[str]]] = []
    for case in corpus.cases:
        candidates = retriever.search(case.question, case.tenant_id, case.top_k)
        paths = [str(candidate.metadata["source_path"]) for candidate in candidates]
        relevant = set(case.expected_sources)
        rows.append((paths, relevant))
        per_case[case.id] = {
            "recall_at_k": recall_at_k(paths, relevant, case.top_k),
            "reciprocal_rank": reciprocal_rank(paths, relevant),
            "ndcg_at_k": ndcg_at_k(paths, relevant, case.top_k),
        }
    count = len(rows)
    denominator = max(count, 1)
    return RetrievalEvalResult(
        case_count=count,
        recall_at_k=sum(
            recall_at_k(got, rel, corpus.cases[i].top_k)
            for i, (got, rel) in enumerate(rows)
        )
        / denominator,
        mrr=sum(reciprocal_rank(got, rel) for got, rel in rows) / denominator,
        ndcg_at_k=sum(
            ndcg_at_k(got, rel, corpus.cases[i].top_k)
            for i, (got, rel) in enumerate(rows)
        )
        / denominator,
        per_case=per_case,
    )


def load_corpus(path: Path) -> RetrievalEvalCorpus:
    raw: Any = json.loads(path.read_text(encoding="utf-8"))
    return RetrievalEvalCorpus.model_validate(raw)


def main() -> None:
    parser = argparse.ArgumentParser(description="Run ctxd retrieval evaluation")
    parser.add_argument("corpus", type=Path, nargs="?", default=Path("evals/retrieval_corpus.json"))
    parser.add_argument("--output", type=Path)
    parser.add_argument("--database-url", help="Use a migrated PostgreSQL index")
    parser.add_argument("--all-modes", action="store_true")
    parser.add_argument("--real-embeddings", action="store_true")
    parser.add_argument("--candidate-depth", type=int, default=20, choices=(5, 10, 20, 50))
    parser.add_argument("--sequential-hybrid", action="store_true")
    args = parser.parse_args()
    postgres_store: PostgresDocumentStore | None = None
    try:
        if args.database_url:
            postgres_store = PostgresDocumentStore(args.database_url)
            postgres_store.start()
        corpus = load_corpus(args.corpus)
        if args.all_modes:
            model: EmbeddingModel = (
                RealEmbeddingProvider() if args.real_embeddings else FakeHashEmbeddingProvider()
            )
            result: RetrievalEvalResult | RetrievalModeEvalResult = run_mode_evaluation(
                corpus,
                postgres_store,
                model,
                candidate_depth=args.candidate_depth,
                parallel_hybrid=not args.sequential_hybrid,
            )
        else:
            result = run_retrieval_eval(corpus, postgres_store)
        rendered = result.model_dump_json(indent=2)
        if args.output:
            args.output.write_text(rendered + "\n", encoding="utf-8")
        print(rendered)
    finally:
        if postgres_store is not None:
            postgres_store.close()


if __name__ == "__main__":
    main()
